-- Product variants and opening stock
WITH p AS (
    SELECT p.id
    FROM products p
    JOIN subcategories s ON s.id = p.subcategory_id
    JOIN categories c ON c.id = s.category_id
    WHERE c.name = 'Plumbing'
      AND s.name = 'PVC Pipes'
      AND p.name = 'Pressure PVC Pipe'
)
INSERT INTO product_variants
(product_id, sku, brand, size_specification, unit, description, cost_price, selling_price, active)
SELECT id, 'PLU-00001', 'Dura Plast', '1/2 inch',
       'piece', 'Dura Plast Pressure PVC Pipe - 1/2 inch', '0.0',
       '0.0', 'true'
FROM p
ON CONFLICT (sku) DO NOTHING;

INSERT INTO inventory_stock (variant_id, quantity, reorder_level, location)
SELECT id, '0', '5', 'Main Store'
FROM product_variants
WHERE sku = 'PLU-00001'
ON CONFLICT (variant_id) DO UPDATE
SET quantity = EXCLUDED.quantity,
    reorder_level = EXCLUDED.reorder_level,
    location = EXCLUDED.location,
    updated_at = NOW();

